import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_OPT_OUT_VALUES = frozenset({"y", "yes", "true", "1"})
_GMAIL_DOMAINS = frozenset({"gmail.com", "googlemail.com"})
_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"^([0-9]{4,5})-[0-9]{4}$")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_PHONE_MARKERS = ("x", "ext", "#")


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _norm_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw.strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return local + "@" + domain


def _norm_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = raw.lower()
    cuts = [i for i in (s.find(marker) for marker in _PHONE_MARKERS) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    """Return a 5-digit ZIP, or "" if it cannot be normalized."""
    s = raw.strip()
    m = _ZIP_PLUS4_RE.match(s)
    if m:
        s = m.group(1)
    if len(s) == 4 and _all_digits(s):
        s = "0" + s  # Excel dropped the leading zero
    if len(s) == 5 and _all_digits(s):
        return s
    return ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _norm_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _pick(members, field):
    """Choose the value for `field` from a group's records.

    Preference: rows with source "manual", then latest `updated`, then
    earliest input position. Returns "" if no row has a non-empty value.
    """
    cands = [r for r in members if r[field]]  # members are in input order
    if not cands:
        return ""
    # Stable sorts: apply the lowest-priority key first.
    cands.sort(key=lambda r: r["updated"], reverse=True)  # ties keep input order
    cands.sort(key=lambda r: not r["manual"])             # manual rows first
    return cands[0][field]


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with neither a valid email nor phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _norm_email(row.get("email", ""))
        phone = _norm_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        source = row.get("source", "").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": _norm_name(row.get("first_name", "")),
            "last_name": _norm_name(row.get("last_name", "")),
            "zip": _norm_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _norm_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Step 2: union-find to group rows into people (transitive matching).
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for p, rec in enumerate(recs):
        if rec["email"]:
            if rec["email"] in email_seen:
                union(email_seen[rec["email"]], p)
            else:
                email_seen[rec["email"]] = p
        last_key = rec["last_name"].lower()
        if rec["phone"] and last_key:
            key = (rec["phone"], last_key)
            if key in phone_seen:
                union(phone_seen[key], p)
            else:
                phone_seen[key] = p

    groups = {}
    for p in range(len(recs)):
        groups.setdefault(find(p), []).append(p)

    # Step 3: build one output dict per person, ordered by earliest input row.
    ordered = sorted(groups.values(), key=lambda members: members[0])
    result = []
    for members in ordered:
        group = [recs[p] for p in members]
        tags = set().union(*(r["tags"] for r in group))
        result.append({
            "first_name": _pick(group, "first_name"),
            "last_name": _pick(group, "last_name"),
            "zip": _pick(group, "zip"),
            "email": _pick(group, "email"),
            "phone": _pick(group, "phone"),
            "source": _pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
        })
    return result
